// Copies the published v3.5 JSON Schemas (public/schema/v3.5, generated by
// scripts/build-schema-v3.5.py at the repo root) into src/schemas so the
// validator bundles the same files citemaps.org serves.
import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const here = dirname(fileURLToPath(import.meta.url));
const from = join(here, '../../../public/schema/v3.5');
const to = join(here, '../src/schemas');
mkdirSync(to, { recursive: true });
for (const f of ['citemap.schema.json', 'content-file.schema.json']) copyFileSync(join(from, f), join(to, f));
console.log('schemas copied');
